def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def floorAndCeil(tree, x):
    if not tree:
        return [-1, -1]
    val, left, right = parse(tree)
    floor_v = ceil_v = -1
    u = 0
    while u != -1:
        if val[u] == x:
            return [x, x]
        if val[u] < x:
            floor_v = val[u]
            u = right[u]
        else:
            ceil_v = val[u]
            u = left[u]
    return [floor_v, ceil_v]
